import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  Legend,
  ResponsiveContainer
} from "recharts";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./completionpage.css";

interface Evaluation {
  question: string;
  difficulty: string;
  subject: string;
  subtopic: string;
  reference_answer: string;
  user_answer: string;
  explanation: string;
  grammar_score: number;
  cosine_similarity_score: number;
  keyword_score: number;
  llm_relevance_score: number;
  total_score: number;
  time_taken: number;
}

interface SubjectPerformance {
  subject: string;
  total_score: number;
}

interface DifficultyDistribution {
  name: string;
  value: number;
}

const COLORS = ["#0088FE", "#00C49F", "#FFBB28"];

const CompletionPage: React.FC = () => {
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [finalScore, setFinalScore] = useState<number>(0);
  const [overallFeedback, setOverallFeedback] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [totalTimeTaken, setTotalTimeTaken] = useState<number>(0);
  const [subjectPerformance, setSubjectPerformance] = useState<SubjectPerformance[]>([]);
  const [difficultyDistribution, setDifficultyDistribution] = useState<DifficultyDistribution[]>([]);
  
  const { testid: paramTestId } = useParams();

  useEffect(() => {
    const fetchCompletionData = async () => {
      const storedTestId = localStorage.getItem("test_id");
      const testid = paramTestId || storedTestId;
      if (!testid) {
        setError("Test ID not found. Please try again.");
        setLoading(false);
        return;
      }
      try {
        const response = await fetch("http://localhost:5000/view_result", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ testid }),
        });
        const data = await response.json();
        if (response.ok) {
          setEvaluations(data.evaluations);
          setFinalScore(data.final_score);
          setOverallFeedback(data.overall_feedback);
          setTotalTimeTaken(data.total_time_taken);
          setSubjectPerformance(data.subject_performance || []);
          setDifficultyDistribution(data.difficulty_distribution || []);
        } else {
          setError(data.error || "Failed to load completion data.");
        }
      } catch (err) {
        setError("Failed to load completion data.");
      } finally {
        setLoading(false);
      }
    };
    fetchCompletionData();
  }, [paramTestId]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">{error}</div>;

  const formatOverallFeedback = (feedback: string) => {
    const sections = feedback.split("**");
    return sections.map((section, index) => {
      if (section.trim() === "") return null;
      return (
        <div key={index} className="feedback-section">
          <h4>{section.trim()}</h4>
          <p>{sections[index + 1]?.trim()}</p>
        </div>
      );
    });
  };

  const getSubjectColor = (subject: string) => {
    const colors: Record<string, string> = {
      "Computer Networks": "#FFD700",
      "Operating Systems": "#FFA500",
      "Data Structures": "#FF6347",
      "Database Systems": "#20B2AA",
      "Object Oriented Programming": "#9370DB"
    };
    return colors[subject] || "#6495ED";
  };

  return (
    <div className="App">
      <Header />
      <div className="cmain-content two-column-layout">
        <div className="charts-column">
          <h2>Performance Analysis</h2>
          
          {subjectPerformance.length > 0 && (
            <div className="chart-container">
              <h3>Subject Performance</h3>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={subjectPerformance}>
                  <XAxis dataKey="subject" />
                  <YAxis domain={[0, 100]} />
                  <Tooltip 
                    formatter={(value: number) => [`${value}%`, "Score"]}
                    labelFormatter={(label) => `Subject: ${label}`}
                  />
                  <Bar 
                    dataKey="total_score" 
                    name="Score"
                    fill="#8884d8"
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {difficultyDistribution.length > 0 && (
            <div className="chart-container">
              <h3>Difficulty Distribution</h3>
              <ResponsiveContainer width="100%" height={400}>
                <PieChart>
                  <Pie 
                    data={difficultyDistribution} 
                    cx="50%" 
                    cy="50%" 
                    outerRadius={100} 
                    dataKey="value"
                    label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                  >
                    {difficultyDistribution.map((_, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip 
                    formatter={(value: number, name: string) => [`${value} questions`, name]}
                  />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>

        <div className="evaluations-column">
          <div className="overall-score-section">
            <h2>Overall Score: {finalScore}%</h2>
            <div className="overall-feedback">
              {formatOverallFeedback(overallFeedback)}
              <h5>Total Time Taken: {totalTimeTaken} minutes</h5>
            </div>
          </div>

          {evaluations.map((evaluation, index) => (
            <div key={index} className="evaluation">
              <div className="evaluation-header">
                <span
                  className="subject"
                  style={{
                    backgroundColor: getSubjectColor(evaluation.subject),
                    color: "black",
                    padding: "2px 8px",
                    borderRadius: "4px"
                  }}
                >
                  {evaluation.subject}
                </span>
                <br />
                <span className="subtopic">
                  <b>Sub-Topics:</b> {evaluation.subtopic}
                </span>
                <br />
                <span
                  className="difficulty"
                  style={{
                    backgroundColor:
                      evaluation.difficulty?.toLowerCase() === "easy"
                        ? "green"
                        : evaluation.difficulty?.toLowerCase() === "hard"
                        ? "red"
                        : "orange",
                    padding: "2px 8px",
                    borderRadius: "4px",
                    color: "white"
                  }}
                >
                  {evaluation.difficulty || "Unknown"}
                </span>
              </div>
              
              <h4>Question {index + 1}: {evaluation.question}</h4>
              <p><strong>Reference Answer:</strong> {evaluation.reference_answer}</p>
              <p><strong>Your Answer:</strong> {evaluation.user_answer}</p>
              <p><strong>Explanation:</strong> {evaluation.explanation}</p>
              
              <div className="scores-grid">
                <div><strong>Grammar Score:</strong> {evaluation.grammar_score}%</div>
                <div><strong>Similarity Score:</strong> {evaluation.cosine_similarity_score}%</div>
                <div><strong>Keyword Score:</strong> {evaluation.keyword_score}%</div>
                <div><strong>Relevance Score:</strong> {evaluation.llm_relevance_score}%</div>
              </div>
              
              <div className="total-score">
                <strong>Total Score:</strong> {evaluation.total_score}%
              </div>
              <div className="time-taken">
                <strong>Time Taken:</strong> {evaluation.time_taken} minutes
              </div>
              <hr />
            </div>
          ))}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default CompletionPage;
